"""MPRD_V1 Test 05R — One-Cell Google Colab Launcher.

Copy this entire file into one Google Colab code cell and run it.
It reconstructs the exact frozen canonical module and Test 05R harness as
separate files, verifies both SHA-256 identities, executes the test, and lets
the verified harness download the complete evidence ZIP.
"""

import base64
import hashlib
import importlib.util
import sys
import zlib
from pathlib import Path

CORE_FILENAME = "MPRD_V1_Canonical_Core_v1_0_1.py"
TEST_FILENAME = "MPRD_V1_Validation_Test_05R_Standalone_Colab.py"
CORE_SHA256 = "daf5bcb9fda5a8e40516bdc22448cb39d03b5f0a259db3b1165bccd92df7df6f"
TEST_SHA256 = "49efecdd115da1a11f8e6ac68e58c8dfc90e3ad63554b6f170589a5ef86fdbd1"

CORE_PAYLOAD = ""
TEST_PAYLOAD = ""


def restore_verified_file(filename, compressed_payload, expected_sha256):
    raw = zlib.decompress(base64.b64decode(compressed_payload))
    actual_sha256 = hashlib.sha256(raw).hexdigest()
    if actual_sha256 != expected_sha256:
        raise RuntimeError(
            f"Embedded payload verification failed for {filename}: "
            f"expected {expected_sha256}, got {actual_sha256}"
        )
    Path(filename).write_bytes(raw)
    written_sha256 = hashlib.sha256(Path(filename).read_bytes()).hexdigest()
    if written_sha256 != expected_sha256:
        raise RuntimeError(f"Written file verification failed for {filename}.")
    print(f"Verified: {filename}")
    print(f"SHA-256: {written_sha256}")
    return Path(filename)


restore_verified_file(CORE_FILENAME, CORE_PAYLOAD, CORE_SHA256)
restore_verified_file(TEST_FILENAME, TEST_PAYLOAD, TEST_SHA256)

spec = importlib.util.spec_from_file_location("mprd_test_05r", TEST_FILENAME)
if spec is None or spec.loader is None:
    raise RuntimeError("Unable to load the reconstructed Test 05R harness.")

test_05r = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = test_05r
spec.loader.exec_module(test_05r)
exit_code = test_05r.main()

if exit_code != 0:
    raise RuntimeError(f"Test 05R completed with failure code {exit_code}.")
print("Test 05R completed successfully.")

